// --- PARAMETRI ---
float zoom = 1.0;       // Collegato alla densità/zoom dell'UI
int max_iter = 100;     // Qualità del dettaglio

// EXPONENT of the formula Z = Z^n + C (slider F), n = 1 + F.
// With F = 1 (the starting value of the sliders) it is the classic Mandelbrot,
// n = 2. Raising F increases the order of symmetry (n = 3: two lobes, n = 4: three,
// ...) and the intermediate values blend one shape into the next continuously.
// Between one integer and the next a cut appears on the left, along the negative
// real half-axis: it is the non-integer power of a complex number, not an
// error, and it disappears again at the next integer value.
// max(): below F = 1 the classic one stays. With n < 2 that cut dominates the
// figure, which comes out shifted and truncated.
float power = 1.0 + max(F, 1.0);

// Center of the fractal: -0.5 is the classic framing for n = 2; with
// higher exponents the figure gathers around the origin.
vec2 center = vec2(-0.5 / (power - 1.0), 0.0);

// --- COORDINATE MAPPING ---
// We map u,v (0.0 - 1.0) onto the complex plane
// We multiply by 3.0 to get a classic initial framing.
// We divide by 'zoom' to enlarge.
vec2 c = (vec2(u, v) - 0.5) * (3.0 / zoom) + center;

// --- LOGICA MANDELBROT (Z = Z^n + C) ---
vec2 z = vec2(0.0);
int iter = 0;

for (int i = 0; i < 100; i++) { // Fixed loop for GLSL (uses max_iter for the break)
    if (i >= max_iter) break;

    // Optimization: if the squared distance > 4, it has escaped
    // (escape radius 2, valid for every n >= 2)
    if (dot(z, z) > 4.0) break;

    if (abs(power - 2.0) < 0.001) {
        // Classic case, in exact and faster arithmetic: (x + iy)^2 + c
        // Real part: x^2 - y^2 + cx
        // Imaginary part: 2xy + cy
        z = vec2(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
    } else {
        // Any exponent, in polar form: the modulus is raised to n,
        // the angle is multiplied by n. z = 0 (the first iteration) must be
        // excluded: atan(0, 0) is not defined on all GPUs.
        float r = length(z);
        vec2 zn = vec2(0.0);
        if (r > 0.0) {
            float ang = atan(z.y, z.x) * power;
            zn = pow(r, power) * vec2(cos(ang), sin(ang));
        }
        z = zn + c;
    }
    iter++;
}

// --- COLORING ---
// We normalize the iterations between 0.0 and 1.0
float tit = float(iter) / float(max_iter);

// We use a square root (pow 0.5) to make the gradient more visible
// and less "all black" at the edges.
tit = sqrt(tit);

// Mix between the user's colors
// tit=0 (immediately outside) -> Color 1
// tit=1 (inside the set)      -> Color 2
return mix(u_col1, u_col2, tit);
